    public static function render(string $name, string $class = 'size-5'): string
    {
        $safeClass = htmlspecialchars($class, ENT_QUOTES, 'UTF-8');

        if (isset(self::FILLED[$name])) {
            $icon = self::FILLED[$name];

            return '<svg class="' . $safeClass . '" viewBox="' . $icon['viewBox'] . '" fill="currentColor"'
                . ' aria-hidden="true" focusable="false">' . $icon['path'] . '</svg>';
        }

        $body = self::PATHS[$name] ?? self::PATHS['file'];

        return '<svg class="' . $safeClass . '" viewBox="0 0 24 24" fill="none" stroke="currentColor"'
            . ' stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"'
            . ' focusable="false">' . $body . '</svg>';
    }

    public static function exists(string $name): bool
    {
        return isset(self::PATHS[$name]) || isset(self::FILLED[$name]);
    }
}
